import type { ImageFlyInProps } from "./image-fly-in";
import type { ComponentType } from "react";
declare const Engine: ComponentType<ImageFlyInProps>;
export default Engine;

"use client";

// Adapted from the user-supplied Annnimate Starter Pack by Good Fella.
// Zeus integration repairs documented in docs/ANNNIMATE.md.

import React, { useRef, useEffect, useState, useCallback } from "react";
import { gsap } from "gsap";
import { useGSAP } from "@gsap/react";
import { ScrollTrigger } from "gsap/dist/ScrollTrigger";
import { SplitText } from "gsap/dist/SplitText";
import { CustomEase } from "gsap/dist/CustomEase";

if (typeof window !== "undefined") {
  gsap.registerPlugin(useGSAP, ScrollTrigger, SplitText, CustomEase);
  CustomEase.create("zeusAnnimate", "M0,0 C0.3,0.9 0.1,1 1,1");
}

const DEFAULT_IMAGES = [
  {
    src: "/assets/annnimate/product_tennis-racket_02.jpg",
    alt: "Tennis racket detail",
    aspect: "portrait_lg",
  },
  {
    src: "/assets/annnimate/product_tennis-racket_05.jpg",
    alt: "Tennis racket detail",
    aspect: "portrait_md",
  },
  {
    src: "/assets/annnimate/product_football-boot_01.jpg",
    alt: "Football boot",
    aspect: "portrait_sm",
  },
  {
    src: "/assets/annnimate/product_half-zip_01.jpg",
    alt: "Half-zip top",
    aspect: "portrait_lg",
    hideMobile: true,
  },
  { src: "/assets/annnimate/product_shoe_01.jpg", alt: "Running shoe", aspect: "portrait_md" },
  {
    src: "/assets/annnimate/product_ball_02.jpg",
    alt: "Ball detail",
    aspect: "portrait_sm",
    hideMobile: true,
  },
  {
    src: "/assets/annnimate/product_tennis-net_01.jpg",
    alt: "Tennis net",
    aspect: "portrait_lg",
    hideMobile: true,
  },
  {
    src: "/assets/annnimate/product_football-boot_06.jpg",
    alt: "Football boot, side view",
    aspect: "landscape_lg",
  },
  {
    src: "/assets/annnimate/product_shoe_06.jpg",
    alt: "Sneaker, side view",
    aspect: "landscape_sm",
    hideMobile: true,
  },
  {
    src: "/assets/annnimate/texture_tennis-macro_01.jpg",
    alt: "Tennis ball macro texture",
    aspect: "square_lg",
  },
  {
    src: "/assets/annnimate/scatter_ball-rackets_01.jpg",
    alt: "Ball and rackets",
    aspect: "square_sm",
    hideMobile: true,
  },
  {
    src: "/assets/annnimate/texture_fabric-macro_01.jpg",
    alt: "Fabric macro texture",
    aspect: "square_sm",
  },
];

const EXIT_Z = 400;
const PLATEAU_Z_START = -200;
const PLATEAU_Z_END = -80;
const HOLE_X_MAX = 0.42;
const HOLE_Y_MAX = 0.35;
const HOLE_SOFT_EDGE = 80;
const VELOCITY_LERP = 0.06;
const VELOCITY_DIVISOR = 60;
const PAN_LERP_DUR = 1.2;
const PAN_Y_RATIO = 0.8;

function smoothstep(t) {
  return t * t * (3 - 2 * t);
}

function clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

/**
 * ImageFlyIn
 *
 * Full-viewport dark 3D depth field. Imagery continuously flies in from deep
 * inside the page toward the viewer, fading in and out around the centre
 * content, with cursor pan parallax on the whole 3D stage. The content
 * element's rectangle is MEASURED and images never spawn inside it.
 *
 * @param {string}  [className='']       - Additional CSS classes for the root element
 * @param {Array}   [images]             - Array of { src, alt, aspect, hideMobile } - defaults to the 12 VANTA demo images
 * @param {string}  [headline]           - Manifesto headline text
 * @param {string}  [support]            - Support paragraph under the headline
 * @param {number}  [duration=10]        - Full fly-in cycle length in seconds at base speed
 * @param {number}  [depth=2000]         - Spawn depth in px
 * @param {number}  [speed=1]            - Base drift speed multiplier
 * @param {number}  [scrollBoost=3.5]    - Max scroll-velocity speed multiplier (0 disables)
 * @param {number}  [pan=40]             - Max cursor pan of the field in px (0 disables cursor parallax)
 * @param {number}  [holeBuffer=120]      - Extra px of clearance around the measured content zone
 */
export default function ImageFlyIn({
  className = "",
  images = DEFAULT_IMAGES,
  headline = "Everything else is noise.",
  support = "Focus is what remains when the season strips away everything you do not need.",
  duration = 10,
  depth = 2000,
  speed = 1,
  scrollBoost = 3.5,
  pan = 40,
  holeBuffer = 120,
}) {
  const rootRef = useRef(null);
  const stageRef = useRef(null);
  const contentRef = useRef(null);
  const headlineRef = useRef(null);
  const supportRef = useRef(null);
  const cardRefs = useRef([]);
  cardRefs.current = [];

  const [fontsLoaded, setFontsLoaded] = useState(false);

  useEffect(() => {
    const p = document.fonts && document.fonts.ready ? document.fonts.ready : Promise.resolve();
    p.then(() => setFontsLoaded(true));
  }, []);

  const addCardRef = useCallback((el) => {
    if (el && !cardRefs.current.includes(el)) cardRefs.current.push(el);
  }, []);

  useGSAP(
    () => {
      const root = rootRef.current;
      const stage = stageRef.current;
      const content = contentRef.current;
      const headlineEl = headlineRef.current;
      const supportEl = supportRef.current;
      const cards = Array.from(stage?.querySelectorAll("[data-anm-ifi-card]") || []);

      if (!root || !stage || !cards.length) return;

      const reducedMQ = window.matchMedia("(prefers-reduced-motion: reduce)");
      const isCoarsePointer = window.matchMedia("(pointer: coarse)").matches;
      let reduced = reducedMQ.matches;

      let viewportW = root.clientWidth;
      let viewportH = root.clientHeight;
      let velocityMultiplier = 1;
      let lastScrollY = window.scrollY || window.pageYOffset || 0;
      let running = false;

      const cardStates = [];
      const setters = [];

      let holeXHalfPx = 0;
      let holeYHalfPx = 0;
      const perspectivePx = parseFloat(getComputedStyle(root).perspective) || 1200;
      const cardHalfW = [];
      const cardHalfH = [];

      // Measure the centre content element and derive the spawn-free zone from
      // its actual rectangle plus the buffer. No content = no exclusion.
      function measureHole() {
        holeXHalfPx = 0;
        holeYHalfPx = 0;
        if (!content) return;
        const rect = content.getBoundingClientRect();
        if (!rect.width || !rect.height) return;
        holeXHalfPx = Math.min(rect.width / 2 + holeBuffer, viewportW * HOLE_X_MAX);
        holeYHalfPx = Math.min(rect.height / 2 + holeBuffer, viewportH * HOLE_Y_MAX);
      }

      // The spawn test and the per-frame zone fade need the card EDGES, not
      // just its centre.
      function measureCards() {
        cards.forEach((card, i) => {
          cardHalfW[i] = card.offsetWidth / 2;
          cardHalfH[i] = card.offsetHeight / 2;
        });
      }

      function randomScatterPosition(halfW, halfH) {
        let x,
          y,
          attempts = 0;
        do {
          x = Math.random() - 0.5;
          y = Math.random() - 0.5;
          attempts += 1;
        } while (
          Math.abs(x) * viewportW < holeXHalfPx + halfW &&
          Math.abs(y) * viewportH < holeYHalfPx + halfH &&
          attempts < 12
        );
        return { xFrac: x, yFrac: y };
      }

      function spawnCard(state, delayIntoCycle, i) {
        const pos = randomScatterPosition(cardHalfW[i] || 0, cardHalfH[i] || 0);
        state.xFrac = pos.xFrac;
        state.yFrac = pos.yFrac;
        state.progress = delayIntoCycle || 0;
      }

      // Per-frame dim so a card never reads on top of the content zone. Works
      // in PROJECTED screen space: the perspective divide pulls far cards
      // toward the centre and the cursor pan shifts the whole field, so a
      // spawn-time test alone cannot keep the zone clear.
      function holeFadeFactor(i, z, panX, panY) {
        if (!holeXHalfPx && !holeYHalfPx) return 1;
        const s = perspectivePx / (perspectivePx - z);
        const state = cardStates[i];
        const projX = (state.xFrac * viewportW + panX) * s;
        const projY = (state.yFrac * viewportH + panY) * s;
        const sepX = Math.abs(projX) - (holeXHalfPx + (cardHalfW[i] || 0) * s);
        const sepY = Math.abs(projY) - (holeYHalfPx + (cardHalfH[i] || 0) * s);
        return smoothstep(clamp01(Math.max(sepX, sepY) / HOLE_SOFT_EDGE));
      }

      function opacityForZ(z) {
        if (z <= -depth) return 0;
        if (z < PLATEAU_Z_START) {
          const t = (z + depth) / (PLATEAU_Z_START + depth);
          return smoothstep(clamp01(t));
        }
        if (z <= PLATEAU_Z_END) return 1;
        if (z < EXIT_Z) {
          const t = (z - PLATEAU_Z_END) / (EXIT_Z - PLATEAU_Z_END);
          return 1 - smoothstep(clamp01(t));
        }
        return 0;
      }

      function buildCardStates() {
        cardStates.length = 0;
        setters.length = 0;
        cards.forEach((card, i) => {
          const state = { xFrac: 0, yFrac: 0, progress: i / cards.length };
          cardStates.push(state);
          spawnCard(state, i / cards.length, i);
          setters.push({
            x: gsap.quickSetter(card, "x", "px"),
            y: gsap.quickSetter(card, "y", "px"),
            z: gsap.quickSetter(card, "z", "px"),
            opacity: gsap.quickSetter(card, "opacity"),
          });
        });
      }

      function tick() {
        if (!running) return;
        const dt = gsap.ticker.deltaRatio(60) / 60;
        const rate = (speed * velocityMultiplier) / duration;
        velocityMultiplier += (1 - velocityMultiplier) * VELOCITY_LERP;
        const totalTravel = EXIT_Z - -depth;

        const panX = quickPanX ? Number(gsap.getProperty(stage, "x")) || 0 : 0;
        const panY = quickPanY ? Number(gsap.getProperty(stage, "y")) || 0 : 0;

        for (let i = 0; i < cardStates.length; i++) {
          const state = cardStates[i];
          state.progress += rate * dt;
          if (state.progress >= 1) spawnCard(state, state.progress - 1, i);

          const z = -depth + state.progress * totalTravel;
          const opacity = opacityForZ(z) * holeFadeFactor(i, z, panX, panY);
          setters[i].x(state.xFrac * viewportW);
          setters[i].y(state.yFrac * viewportH);
          setters[i].z(z);
          setters[i].opacity(opacity);
        }
      }

      function startTicker() {
        if (running) return;
        running = true;
        gsap.ticker.add(tick);
      }

      function stopTicker() {
        running = false;
        gsap.ticker.remove(tick);
      }

      // Cursor pan (no rotation): the field slides WITH the pointer - cursor
      // left moves the field further left. Perspective makes near cards shift
      // more than far ones, so depth parallax comes for free. Long quickTo
      // duration keeps it fluid rather than responsive.
      let quickPanX, quickPanY;

      function onPointerMove(e) {
        const rect = root.getBoundingClientRect();
        const nx = ((e.clientX - rect.left) / rect.width) * 2 - 1;
        const ny = ((e.clientY - rect.top) / rect.height) * 2 - 1;
        quickPanX(nx * pan);
        quickPanY(ny * pan * PAN_Y_RATIO);
      }

      function onPointerLeave() {
        quickPanX(0);
        quickPanY(0);
      }

      if (!isCoarsePointer && !reduced && pan > 0) {
        quickPanX = gsap.quickTo(stage, "x", { duration: PAN_LERP_DUR, ease: "power3.out" });
        quickPanY = gsap.quickTo(stage, "y", { duration: PAN_LERP_DUR, ease: "power3.out" });
        root.addEventListener("pointermove", onPointerMove);
        root.addEventListener("pointerleave", onPointerLeave);
      }

      function onScroll() {
        const y = window.scrollY || window.pageYOffset || 0;
        const dlt = Math.abs(y - lastScrollY);
        lastScrollY = y;
        if (scrollBoost > 0) {
          const boost = 1 + Math.min(dlt / VELOCITY_DIVISOR, 1) * (scrollBoost - 1);
          velocityMultiplier = Math.max(velocityMultiplier, boost);
        }
      }
      window.addEventListener("scroll", onScroll, { passive: true });

      let resizeTimer;
      function onResize() {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(() => {
          viewportW = root.clientWidth;
          viewportH = root.clientHeight;
          measureHole();
          measureCards();
          ScrollTrigger.refresh();
        }, 150);
      }
      window.addEventListener("resize", onResize);

      let isIntersecting = true;
      let io = null;
      if ("IntersectionObserver" in window) {
        io = new IntersectionObserver(
          (entries) => {
            entries.forEach((entry) => {
              isIntersecting = entry.isIntersecting;
              if (isIntersecting && !document.hidden && !reduced) startTicker();
              else stopTicker();
            });
          },
          { threshold: 0 },
        );
        io.observe(root);
      }

      function onVisibilityChange() {
        if (document.hidden) {
          stopTicker();
        } else {
          if (isIntersecting && !reduced) startTicker();
        }
      }
      document.addEventListener("visibilitychange", onVisibilityChange);

      // --- Headline reveal (ordinary scroll-enter, SplitText line masks) ---
      let split = null;
      let supportSplit = null;
      let revealTl = null;
      let revealSt = null;
      let revealFrame = 0;

      if (fontsLoaded && headlineEl) {
        split = SplitText.create(headlineEl, {
          type: "lines",
          mask: "lines",
          linesClass: "ifi_headline_line",
        });
        if (supportEl)
          supportSplit = SplitText.create(supportEl, {
            type: "lines",
            mask: "lines",
            linesClass: "ifi_support_line",
          });

        const headlineLines = split.lines;
        const supportLines = supportSplit ? supportSplit.lines : [];

        gsap.set(headlineLines, { yPercent: 110, y: 0 });
        if (supportLines.length) gsap.set(supportLines, { yPercent: 110, y: 0 });

        revealTl = gsap.timeline({
          paused: true,
          defaults: { ease: "zeusAnnimate", force3D: true },
        });
        revealTl.fromTo(
          headlineLines,
          { yPercent: 110, y: 0 },
          { yPercent: 0, y: 0, duration: 1.1, stagger: 0.08 },
        );
        if (supportLines.length) {
          revealTl.fromTo(
            supportLines,
            { yPercent: 110, y: 0 },
            { yPercent: 0, y: 0, duration: 0.9, stagger: 0.05 },
            "-=0.6",
          );
        }

        function inFirstViewport() {
          const r = root.getBoundingClientRect();
          return r.top < root.clientHeight && r.bottom > 0;
        }

        revealFrame = requestAnimationFrame(() => {
          if (inFirstViewport()) {
            if (reduced) revealTl.progress(1);
            else revealTl.restart();
          } else {
            revealSt = ScrollTrigger.create({
              trigger: root,
              start: "top 80%",
              once: true,
              onEnter: () => revealTl.restart(),
            });
          }
          ScrollTrigger.refresh();
        });
      }

      // --- Init ---
      gsap.set(cards, {
        xPercent: -50,
        yPercent: -50,
        force3D: true,
        willChange: "transform, opacity",
      });
      gsap.set(stage, { force3D: true });
      if (content) gsap.set(content, { force3D: true });
      measureHole();
      measureCards();
      buildCardStates();

      if (reduced) {
        cards.forEach((card, i) => {
          const state = cardStates[i];
          gsap.set(card, {
            x: state.xFrac * viewportW,
            y: state.yFrac * viewportH,
            z: -200,
            opacity: 0.9,
          });
        });
        if (revealTl) revealTl.progress(1);
      } else {
        startTicker();
      }

      return () => {
        stopTicker();
        cancelAnimationFrame(revealFrame);
        clearTimeout(resizeTimer);
        quickPanX?.tween?.kill();
        quickPanY?.tween?.kill();
        window.removeEventListener("scroll", onScroll);
        window.removeEventListener("resize", onResize);
        root.removeEventListener("pointermove", onPointerMove);
        root.removeEventListener("pointerleave", onPointerLeave);
        document.removeEventListener("visibilitychange", onVisibilityChange);
        if (io) io.disconnect();
        if (revealTl) revealTl.kill();
        if (revealSt) revealSt.kill();
        if (split) split.revert();
        if (supportSplit) supportSplit.revert();
      };
    },
    {
      scope: rootRef,
      revertOnUpdate: true,
      dependencies: [
        fontsLoaded,
        images,
        headline,
        support,
        duration,
        depth,
        speed,
        scrollBoost,
        pan,
        holeBuffer,
      ],
    },
  );

  return (
    <section
      ref={rootRef}
      className={`ifi_section${className ? " " + className : ""}`}
      data-anm-image-fly-in
    >
      <div ref={stageRef} className="ifi_stage" data-anm-ifi-stage>
        {images.map((img, i) => (
          <div
            key={img.src + i}
            ref={addCardRef}
            className={`ifi_card ifi_card_${img.aspect}${img.hideMobile ? " ifi_card_hide_mobile" : ""}`}
            data-anm-ifi-card
          >
            <img className="ifi_card_img" src={img.src} alt={img.alt || ""} />
          </div>
        ))}
      </div>

      <div ref={contentRef} className="ifi_content" data-anm-ifi-content>
        <h2 ref={headlineRef} className="ifi_headline" data-anm-ifi-headline>
          {headline}
        </h2>
        {support ? (
          <p ref={supportRef} className="ifi_support" data-anm-ifi-support>
            {support}
          </p>
        ) : null}
      </div>
    </section>
  );
}

// Styles adapted from the supplied Annnimate Starter Pack.
const css = `/* Image Fly-In
   Dark full-viewport 3D depth field. Imagery flies in from deep inside the
   page toward the viewer around a central content hole, with cursor-bend
   parallax on the whole 3D stage. No Webflow - CSS variables and @font-face
   allowed. */



/* ---- Tokens ---- */
.ifi_section {
  --ifi-bg:      #0d0908;
  --ifi-ink:     #ffffff;
  --ifi-muted:   rgba(255, 255, 255, 0.55);
  --ifi-radius:  10px;
  --ifi-sans:    var(--font-inter, Inter), -apple-system, BlinkMacSystemFont, sans-serif;
  --ifi-perspective: 1200px;
}

/* ---- Root ---- */
.ifi_section {
  position: relative;
  width: 100%;
  min-height: var(--zeus-animation-height, 640px);
  box-sizing: border-box;
  background: var(--ifi-bg);
  color: var(--ifi-ink);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  perspective: var(--ifi-perspective);
  font-family: var(--ifi-sans);
  -webkit-font-smoothing: antialiased;
}

/* The 3D stage: preserves 3D for all card children, bent toward the cursor by
   JS (rotationX/rotationY via quickTo). Fills the section. */
.ifi_stage {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  will-change: transform;
}

/* ---- Manifesto headline block ----
   Sits outside the rotating stage (own layer) so it stays readable; carries
   only a small counter-tilt set directly by JS. */
.ifi_content {
  position: relative;
  z-index: 2;
  max-width: 720px;
  margin: 0 auto;
  padding: 0 24px;
  text-align: center;
  transform-style: preserve-3d;
  will-change: transform;
  pointer-events: none;
}

.ifi_headline {
  font-family: var(--ifi-sans);
  font-weight: 400;
  font-size: clamp(32px, 4.2vw, 58px);
  line-height: 1;
  letter-spacing: -0.05em;
  color: var(--ifi-ink);
  margin: 0;
  overflow-x: visible;
  overflow-y: visible;
}

/* SplitText mask: "lines" wraps each line in its own clip box; the padding
   grows the line box so the mask clips below descenders at tight leading. */
.ifi_headline_line {
  padding-bottom: 0.18em;
}

.ifi_support {
  font-family: var(--ifi-sans);
  font-weight: 380;
  font-size: 15px;
  line-height: 1.6;
  color: var(--ifi-muted);
  margin: 8px auto 0;
  max-width: 380px;
}

.ifi_support_line {
  padding-bottom: 0.18em;
}

/* ---- Image cards ----
   Positioned at the stage centre; JS drives x/y/z/opacity per-card via
   quickSetters. transform-origin centre so depth scaling reads naturally
   through the perspective. Native aspect ratio per card - set inline via a
   per-card modifier class matched to its own image's w/h so nothing crops. */
.ifi_card {
  position: absolute;
  top: 50%;
  left: 50%;
  border-radius: var(--ifi-radius);
  overflow: hidden;
  transform-style: preserve-3d;
  transform-origin: 50% 50%;
  will-change: transform, opacity;
  opacity: 0;
  backface-visibility: hidden;
}

.ifi_card_img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Card size registers, matched to each image's native aspect so cover never
   mismatch-crops. Widths scale between mobile and desktop via clamp. */
.ifi_card_portrait_sm {
  width: clamp(90px, 8vw, 140px);
  aspect-ratio: 3072 / 3840;
}

.ifi_card_portrait_md {
  width: clamp(130px, 11vw, 190px);
  aspect-ratio: 2888 / 3840;
}

.ifi_card_portrait_lg {
  width: clamp(170px, 14vw, 260px);
  aspect-ratio: 3072 / 3840;
}

.ifi_card_landscape_sm {
  width: clamp(140px, 12vw, 210px);
  aspect-ratio: 3840 / 2568;
}

.ifi_card_landscape_lg {
  width: clamp(190px, 16vw, 260px);
  aspect-ratio: 3840 / 2568;
}

.ifi_card_square_sm {
  width: clamp(100px, 9vw, 150px);
  aspect-ratio: 1 / 1;
}

.ifi_card_square_lg {
  width: clamp(150px, 13vw, 220px);
  aspect-ratio: 1 / 1;
}

/* ---- Responsive: deliberate mobile field, not a squashed desktop ----
   Fewer cards, smaller scale range, no cursor parallax (handled in JS via
   pointer:coarse guard), headline already scales via clamp. */
@media (max-width: 767px), (pointer: coarse) {
  .ifi_card_hide_mobile {
    display: none;
  }

  .ifi_card_portrait_sm,
  .ifi_card_square_sm {
    width: clamp(70px, 20vw, 100px);
  }

  .ifi_card_portrait_md {
    width: clamp(90px, 24vw, 120px);
  }

  .ifi_card_portrait_lg,
  .ifi_card_landscape_lg,
  .ifi_card_square_lg {
    width: clamp(110px, 30vw, 160px);
  }

  .ifi_card_landscape_sm {
    width: clamp(100px, 26vw, 140px);
  }

  .ifi_content {
    padding: 0 20px;
  }

  .ifi_support {
    max-width: 280px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ifi_card,
  .ifi_stage,
  .ifi_content {
    will-change: auto;
  }
}
`;
export default css;

"use client";

// Annnimate Starter Pack adaptation. See docs/ANNNIMATE.md for provenance.
import Engine from "./image-fly-in-engine.jsx";
import css from "./image-fly-in-styles";

export interface FlyInImage {
  src: string;
  alt?: string;
  aspect?:
    | "portrait_sm"
    | "portrait_md"
    | "portrait_lg"
    | "landscape_sm"
    | "landscape_lg"
    | "square_sm"
    | "square_lg";
  hideMobile?: boolean;
}
export interface ImageFlyInProps {
  className?: string;
  images?: FlyInImage[];
  headline?: string;
  support?: string;
  duration?: number;
